use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        // DropSeen: keep only items whose id is not already recorded in the
        // 'seen' store. The handle is read-only (state-read has no `put`), so
        // this node observes the store but cannot change what the next run sees.
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
